nb,boolean,integer)","acl_values":["postgres=X/postgres","service_role=X/postgres"],"owner":"postgres","config":["search_path=pg_catalog, public"],"definer":false,"strict":false,"volatility":"v","language":"plpgsql","returns":"jsonb","parallel":"u","cost":100,"rows":0,"leakproof":false,"support":"-","definition_hashes":["6e502cf4dba93421eaced42b13e055c6","e59979cd07a348564e4f7e0c897c932b"]},{"signature":"pos_sync_pull(text,text,text,bigint,integer)","acl_values":["postgres=X/postgres","service_role=X/postgres"],"owner":"postgres","config":["search_path=public, pg_temp"],"definer":true,"strict":false,"volatility":"v","language":"plpgsql","returns":"TABLE(cursor bigint, table_name text, entity_id text, operation text, row_version bigint, tombstone boolean, row_data jsonb)","parallel":"u","cost":100,"rows":1000,"leakproof":false,"support":"-","definition_hashes":["e3171846683edb5d58c7a5291526555a","7948d5af4bac8501f3a5bf501099aa48"]},{"signature":"pos_sync_validate_read_scope(text,text,text)","acl_values":["postgres=X/postgres","service_role=X/postgres"],"owner":"postgres","config":["search_path=public, pg_temp"],"definer":true,"strict":false,"volatility":"v","language":"plpgsql","returns":"void","parallel":"u","cost":100,"rows":0,"leakproof":false,"support":"-","definition_hashes":["99b7c7e0758c07c45f1abeaec2f40526"]},{"signature":"pos_sync_validate_scope(text,text,text)","acl_values":["postgres=X/postgres","service_role=X/postgres"],"owner":"postgres","config":["search_path=public, pg_temp"],"definer":true,"strict":false,"volatility":"v","language":"plpgsql","returns":"void","parallel":"u","cost":100,"rows":0,"leakproof":false,"support":"-","definition_hashes":["987c6972d40518c2431cad4711bcd11b"]}]$history_transport_data$::jsonb;
 targets constant jsonb := $history_transport_data$[{"signature":"pos_sync_history_company_scope_transport_v1(text,text,text)","acl_values":["postgres=X/postgres","service_role=X/postgres"],"owner":"postgres","config":["search_path=pg_catalog, public"],"definer":false,"strict":false,"volatility":"v","language":"plpgsql","returns":"boolean","parallel":"u","cost":100,"rows":0,"leakproof":false,"support":"-","body_md5":"5394e4cb7ef5b1ad33465ce7214cf3c8","arguments":"p_organization_id text, p_branch_id text, p_terminal_id text","definition":"\u0043REATE FUNCTION public.pos_sync_history_company_scope_transport_v1(p_organization_id text,p_branch_id text,p_terminal_id text)\nRETURNS boolean LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public AS $history_scope$\nBEGIN\n PERFORM public.pos_sync_validate_read_scope(p_organization_id,p_branch_id,p_terminal_id);\n RETURN EXISTS(SELECT 1 FROM public.terminal_tokens t WHERE t.id::text=p_terminal_id\n  AND t.platform='pc' AND t.location_id IS NULL AND t.management_sync_enabled\n  AND t.is_claimed AND t.status IN ('active','used') AND t.revoked_at IS NULL);\nEND;\n$history_scope$;"},{"signature":"pos_sync_history_row_visible_transport_v1(boolean,text,text,text,text,text)","acl_values":["postgres=X/postgres","service_role=X/postgres"],"owner":"postgres","config":["search_path=pg_catalog"],"definer":false,"strict":false,"volatility":"i","language":"sql","returns":"boolean","parallel":"u","cost":100,"rows":0,"leakproof":false,"support":"-","body_md5":"6ea7a6c65e826887d0f79c9e6bab6d20","arguments":"p_company boolean, p_organization_id text, p_branch_id text, p_row_organization_id text, p_scope_type text, p_scope_id text","definition":"\u0043REATE FUNCTION public.pos_sync_history_row_visible_transport_v1(p_company boolean,p_organization_id text,p_branch_id text,p_row_organization_id text,p_scope_type text,p_scope_id text)\nRETURNS boolean LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $history_scope$\n SELECT COALESCE(p_row_organization_id COLLATE \"C\"=p_organization_id COLLATE \"C\" AND\n  (p_company IS TRUE OR (p_scope_type COLLATE \"C\"='BRANCH' AND CASE\n   WHEN p_scope_id COLLATE \"C\" ~ '^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}$'\n    AND p_branch_id COLLATE \"C\" ~ '^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}$'\n   THEN lower(p_scope_id)=lower(p_branch_id) ELSE p_scope_id COLLATE \"C\"=p_branch_id COLLATE \"C\" END)),false);\n$history_scope$;"},{"signature":"pos_sync_pull_history_v2(text,text,text,bigint,integer)","acl_values":["postgres=X/postgres","service_role=X/postgres"],"owner":"postgres","config":["search_path=public, pg_temp"],"definer":true,"strict":false,"volatility":"v","language":"plpgsql","returns":"TABLE(cursor bigint, table_name text, entity_id text, operation text, row_version bigint, tombstone boolean, row_data jsonb)","parallel":"u","cost":100,"rows":1000,"leakproof":false,"support":"-","body_md5":"2ec6c44745fb10a389c0be6870bbf384","definition_md5":"34f17c081b8a69e687880c6b67bf7217","definition":"\u0043REATE FUNCTION public.pos_sync_pull_history_v2(p_organization_id text, p_branch_id text, p_terminal_id text, p_after_cursor bigint DEFAULT 0, p_limit integer DEFAULT 500)\n RETURNS TABLE(cursor bigint, table_name text, entity_id text, operation text, row_version bigint, tombstone boolean, row_data jsonb)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n v_history_company boolean; v_me public.app_users%ROWTYPE;\nBEGIN v_history_company := public.pos_sync_history_company_scope_transport_v1(p_organization_id,p_branch_id,p_terminal_id); IF auth.role()<>'service_role' THEN SELECT * INTO v_me FROM public.app_users WHERE auth_user_id=auth.uid() AND is_active=true LIMIT 1;\n IF v_me.id IS NULL OR NOT (v_me.role='admin' OR COALESCE((v_me.permissions->>'can_manage_sync_backup')::boolean,false)) THEN RAISE EXCEPTION 'SYNC_FORBIDDEN'; END IF;\n IF NOT (v_me.role='admin' OR v_me.store_id IS NULL OR v_me.store_id=p_branch_id) THEN RAISE EXCEPTION 'SYNC_BRANCH_FORBIDDEN'; END IF; END IF;\n -- cluster-catalogue-read-filter\n RETURN QUERY WITH feed_page AS MATERIALIZED (\n  SELECT candidate.cursor,candidate.table_name,candidate.entity_id,candidate.operation,candidate.row_version,candidate.tombstone\n  FROM (SELECT DISTINCT unnest(ARRAY[p_branch_id,'global']) AS branch_id) scopes\n  CROSS JOIN LATERAL (\n   (SELECT c.cursor,c.table_name,c.entity_id,c.operation,c.row_version,c.tombstone\n    FROM public.sync_change_feed c\n    WHERE c.organization_id=p_organization_id AND c.branch_id=scopes.branch_id\n      AND c.terminal_id IS NULL AND c.cursor>p_after_cursor AND (c.table_name<>'change_history' OR (NOT c.tombstone AND EXISTS(SELECT 1 FROM public.change_history history_scope_row WHERE history_scope_row.id=((c.entity_id::jsonb)->>'id')::uuid AND public.pos_sync_history_row_visible_transport_v1(v_history_company,p_organization_id,p_branch_id,history_scope_row.organization_id,history_scope_row.scope_type,history_scope_row.scope_id))))\n    ORDER BY c.cursor LIMIT LEAST(GREATEST(p_limit,10),2000))\n   UNION ALL\n   (SELECT c.cursor,c.table_name,c.entity_id,c.operation,c.row_version,c.tombstone\n    FROM public.sync_change_feed c\n    WHERE c.organization_id=p_organization_id AND c.branch_id=scopes.branch_id\n      AND c.terminal_id=p_terminal_id AND c.terminal_id IS NOT NULL AND c.cursor>p_after_cursor AND (c.table_name<>'change_history' OR (NOT c.tombstone AND EXISTS(SELECT 1 FROM public.change_history history_scope_row WHERE history_scope_row.id=((c.entity_id::jsonb)->>'id')::uuid AND public.pos_sync_history_row_visible_transport_v1(v_history_company,p_organization_id,p_branch_id,history_scope_row.organization_id,history_scope_row.scope_type,history_scope_row.scope_id))))\n    ORDER BY c.cursor LIMIT LEAST(GREATEST(p_limit,10),2000))\n  ) candidate\n  ORDER BY candidate.cursor LIMIT LEAST(GREATEST(p_limit,10),2000)\n )\n SELECT f.cursor,f.table_name,f.entity_id,f.operation,f.row_version,f.tombstone,CASE f.table_name WHEN 'coupon_campaigns' THEN (SELECT to_jsonb(x) FROM public.\"coupon_campaigns\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'shifts' THEN (SELECT to_jsonb(x) FROM public.\"shifts\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'issued_vouchers' THEN (SELECT to_jsonb(x) FROM public.\"issued_vouchers\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'activity_events' THEN (SELECT to_jsonb(x) FROM public.\"activity_events\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'app_users' THEN (SELECT to_jsonb(x) FROM public.\"app_users\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'audit_logs' THEN (SELECT to_jsonb(x) FROM public.\"audit_logs\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'booking_payments' THEN (SELECT to_jsonb(x) FROM public.\"booking_payments\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'bookings' THEN (SELECT to_jsonb(x) FROM public.\"bookings\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'branch_telemetry' THEN (SELECT to_jsonb(x) FROM public.\"branch_telemetry\" x WHERE x.\"terminal_id\"=((f.entity_id::jsonb)->>'terminal_id') LIMIT 1)\n    WHEN 'cashiers' THEN (SELECT to_jsonb(x) FROM public.\"cashiers\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'coupon_events' THEN (SELECT to_jsonb(x) FROM public.\"coupon_events\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'drawer_events' THEN (SELECT to_jsonb(x) FROM public.\"drawer_events\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'held_orders' THEN (SELECT to_jsonb(x) FROM public.\"held_orders\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id') LIMIT 1)\n    WHEN 'integration_settings' THEN (SELECT to_jsonb(x) FROM public.\"integration_settings\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'item_activity_logs' THEN (SELECT to_jsonb(x) FROM public.\"item_activity_logs\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'member_verifications' THEN (SELECT to_jsonb(x) FROM public.\"member_verifications\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'members' THEN (SELECT to_jsonb(x) - ARRAY['auth_user_id']::text[] FROM public.\"members\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'membership_tiers' THEN (SELECT to_jsonb(x) FROM public.\"membership_tiers\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'offline_sync_audit_log' THEN (SELECT to_jsonb(x) FROM public.\"offline_sync_audit_log\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'payment_transactions' THEN (SELECT to_jsonb(x) FROM public.\"payment_transactions\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'payment_types' THEN (SELECT to_jsonb(x) FROM public.\"payment_types\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'pin_attempts' THEN (SELECT to_jsonb(x) FROM public.\"pin_attempts\" x WHERE x.\"key\"=((f.entity_id::jsonb)->>'key') LIMIT 1)\n    WHEN 'pos_settings' THEN (SELECT to_jsonb(x) FROM public.\"pos_settings\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::integer LIMIT 1)\n    WHEN 'product_barcodes' THEN (SELECT to_jsonb(x) FROM public.\"product_barcodes\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid AND public.product_available_in_catalogue(x.product_id,p_branch_id) LIMIT 1)\n    WHEN 'product_categories' THEN (SELECT to_jsonb(x) FROM public.\"product_categories\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'products' THEN (SELECT to_jsonb(x) FROM public.\"products\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid AND public.product_available_in_catalogue(x.id,p_branch_id) LIMIT 1)\n    WHEN 'promotions' THEN (SELECT to_jsonb(x) FROM public.\"promotions\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid AND (x.foc_product_id IS NULL OR public.product_available_in_catalogue(x.foc_product_id,p_branch_id)) LIMIT 1)\n    WHEN 'public_flags' THEN (SELECT to_jsonb(x) FROM public.\"public_flags\" x WHERE x.\"key\"=((f.entity_id::jsonb)->>'key') LIMIT 1)\n    WHEN 'purchase_order_items' THEN (SELECT to_jsonb(x) FROM public.\"purchase_order_items\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'purchase_orders' THEN (SELECT to_jsonb(x) FROM public.\"purchase_orders\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'sale_items' THEN (SELECT to_jsonb(x) FROM public.\"sale_items\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'sales' THEN (SELECT to_jsonb(x) FROM public.\"sales\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'secure_settings' THEN (SELECT to_jsonb(x) FROM public.\"secure_settings\" x WHERE x.\"key\"=((f.entity_id::jsonb)->>'key') LIMIT 1)\n    WHEN 'security_findings' THEN (SELECT to_jsonb(x) FROM public.\"security_findings\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'settings_locks' THEN (SELECT to_jsonb(x) FROM public.\"settings_locks\" x WHERE x.\"section\"=((f.entity_id::jsonb)->>'section') LIMIT 1)\n    WHEN 'settings_overrides' THEN (SELECT to_jsonb(x) FROM public.\"settings_overrides\" x WHERE x.\"scope\"=((f.entity_id::jsonb)->>'scope') AND x.\"scope_id\"=((f.entity_id::jsonb)->>'scope_id') AND x.\"section\"=((f.entity_id::jsonb)->>'section') LIMIT 1)\n    WHEN 'shift_sessions' THEN (SELECT to_jsonb(x) FROM public.\"shift_sessions\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'sku_audit' THEN (SELECT to_jsonb(x) FROM public.\"sku_audit\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'staff_roles' THEN (SELECT to_jsonb(x) FROM public.\"staff_roles\" x WHERE x.\"slug\"=((f.entity_id::jsonb)->>'slug') LIMIT 1)\n    WHEN 'stock_adjustments' THEN (SELECT to_jsonb(x) FROM public.\"stock_adjustments\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'stock_delta_applied' THEN (SELECT to_jsonb(x) FROM public.\"stock_delta_applied\" x WHERE x.\"movement_id\"=((f.entity_id::jsonb)->>'movement_id')::uuid LIMIT 1)\n    WHEN 'stock_transfer_items' THEN (SELECT to_jsonb(x) FROM public.\"stock_transfer_items\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'stock_transfers' THEN (SELECT to_jsonb(x) FROM public.\"stock_transfers\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'stores' THEN (SELECT to_jsonb(x) FROM public.\"stores\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id') LIMIT 1)\n    WHEN 'suppliers' THEN (SELECT to_jsonb(x) FROM public.\"suppliers\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'sync_metadata' THEN (SELECT to_jsonb(x) FROM public.\"sync_metadata\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'system_audit_logs' THEN (SELECT to_jsonb(x) FROM public.\"system_audit_logs\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'terminal_commands' THEN (SELECT to_jsonb(x) FROM public.\"terminal_commands\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'terminal_tokens' THEN (SELECT to_jsonb(x) FROM public.\"terminal_tokens\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'uom_units' THEN (SELECT to_jsonb(x) FROM public.\"uom_units\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'user_roles' THEN (SELECT to_jsonb(x) FROM public.\"user_roles\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'whatsapp_queue' THEN (SELECT to_jsonb(x) FROM public.\"whatsapp_queue\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'terminal_recovery_secrets' THEN (SELECT to_jsonb(x) FROM public.\"terminal_recovery_secrets\" x WHERE x.\"terminal_token_id\"=((f.entity_id::jsonb)->>'terminal_token_id')::uuid LIMIT 1)\n    WHEN 'pos_store_settings' THEN (SELECT to_jsonb(x) FROM public.\"pos_store_settings\" x WHERE x.\"store_id\"=((f.entity_id::jsonb)->>'store_id') LIMIT 1)\n    WHEN 'settings_scoped' THEN (SELECT to_jsonb(x) FROM public.\"settings_scoped\" x WHERE x.\"scope\"=((f.entity_id::jsonb)->>'scope') AND x.\"scope_id\"=((f.entity_id::jsonb)->>'scope_id') AND x.\"key\"=((f.entity_id::jsonb)->>'key') LIMIT 1)\n    WHEN 'stock_count_drafts' THEN (SELECT to_jsonb(x) FROM public.\"stock_count_drafts\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'authorization_actions' THEN (SELECT to_jsonb(x) FROM public.\"authorization_actions\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'authorization_action_history' THEN (SELECT to_jsonb(x) FROM public.\"authorization_action_history\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'authorization_requests' THEN (SELECT to_jsonb(x) FROM public.\"authorization_requests\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'authorization_log' THEN (SELECT to_jsonb(x) FROM public.\"authorization_log\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'record_edits' THEN (SELECT to_jsonb(x) FROM public.\"record_edits\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'shift_cash_counts' THEN (SELECT to_jsonb(x) FROM public.\"shift_cash_counts\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'shift_close_events' THEN (SELECT to_jsonb(x) FROM public.\"shift_close_events\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'shift_reconciliations' THEN (SELECT to_jsonb(x) FROM public.\"shift_reconciliations\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'shift_variance_alerts' THEN (SELECT to_jsonb(x) FROM public.\"shift_variance_alerts\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'shift_notifications' THEN (SELECT to_jsonb(x) FROM public.\"shift_notifications\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'entity_status_history' THEN (SELECT to_jsonb(x) FROM public.\"entity_status_history\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'nav_pins' THEN (SELECT to_jsonb(x) FROM public.\"nav_pins\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'store_groups' THEN (SELECT to_jsonb(x) FROM public.\"store_groups\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id') LIMIT 1)\n    WHEN 'change_history' THEN (SELECT to_jsonb(x) FROM public.\"change_history\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid AND public.pos_sync_history_row_visible_transport_v1(v_history_company,p_organization_id,p_branch_id,x.organization_id,x.scope_type,x.scope_id) LIMIT 1) ELSE NULL END\n FROM feed_page f ORDER BY f.cursor;\nEND $function$\n"},{"signature":"pos_sync_history_index_v3(text,text,text,text,uuid,uuid,integer,boolean)","acl_values":["postgres=X/postgres","service_role=X/postgres"],"owner":"postgres","config":["search_path=pg_catalog, public"],"definer":false,"strict":false,"volatility":"v","language":"plpgsql","returns":"jsonb","parallel":"u","cost":100,"rows":0,"leakproof":false,"support":"-","body_md5":"471d76ede0b33d288507aef6f45baf6c","definition_md5":"3fe90fa8a66da26b248854c3a740c17b","definition":"\u0043REATE FUNCTION public.pos_sync_history_index_v3(p_organization_id text, p_branch_id text, p_terminal_id text, p_action text, p_after_id uuid DEFAULT NULL::uuid, p_upper_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 1000, p_keep_commerce boolean DEFAULT false)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\nDECLARE\n v_history_company boolean;\n v_upper uuid:=p_upper_id; v_ids jsonb:='[]'::jsonb; v_next uuid; v_more boolean:=false;\n v_count text; v_result jsonb;\nBEGIN\n v_history_company := public.pos_sync_history_company_scope_transport_v1(p_organization_id,p_branch_id,p_terminal_id);\n -- Runtime accepts only the same reviewed projection with LF/CRLF storage,\n -- and the captured-live/current-canonical immutable helper body forms.\n -- The migration's existing-source preflight below remains byte-exact.\n IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('public.pos_sync_history_project_v1(jsonb,text,boolean)')\n  AND md5(replace(p.prosrc,chr(13)||chr(10),chr(10)))='a5be97695f3e105ebde271e2f017ddee'\n  AND pg_get_userbyid(p.proowner)='postgres' AND p.prorettype='jsonb'::regtype AND p.prolang=(SELECT oid FROM pg_language WHERE lanname='plpgsql')\n  AND NOT p.prosecdef AND p.proisstrict AND p.provolatile='i' AND p.proconfig=ARRAY['search_path=pg_catalog'])\n OR NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('public.change_history_immutable()')\n  AND replace(p.prosrc,chr(13)||chr(10),chr(10)) IN (chr(10)||'BEGIN RAISE EXCEPTION ''change_history is append-only''; END ',' BEGIN RAISE EXCEPTION ''change_history is append-only''; END ')\n  AND pg_get_userbyid(p.proowner)='postgres' AND p.prorettype='trigger'::regtype AND p.prolang=(SELECT oid FROM pg_language WHERE lanname='plpgsql')\n  AND NOT p.prosecdef AND NOT p.proisstrict AND p.provolatile='v' AND p.proconfig=ARRAY['search_path=public, pg_temp'])\n OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.change_history'::regclass AND tgname='change_history_no_change' AND tgenabled='O'\n  AND pg_get_triggerdef(oid)='CREATE TRIGGER change_history_no_change BEFORE DELETE OR UPDATE ON public.change_history FOR EACH ROW EXECUTE FUNCTION change_history_immutable()')\n THEN RAISE EXCEPTION 'HISTORY_INDEX_UNSUPPORTED_SOURCE'; END IF;\n IF p_action IS NULL OR p_action NOT IN ('begin','page','finish') OR p_limit IS NULL OR p_limit<1 OR p_limit>1000 OR p_keep_commerce IS NULL\n OR (p_action='begin' AND (p_after_id IS NOT NULL OR p_upper_id IS NOT NULL))\n OR (p_action='page' AND (p_upper_id IS NULL OR p_after_id>p_upper_id))\n OR (p_action='finish' AND p_after_id IS NOT NULL)\n THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='HISTORY_INDEX_INVALID_ARGUMENT'; END IF;\n IF p_action='begin' THEN SELECT h.id INTO v_upper FROM public.change_history h WHERE public.pos_sync_history_row_visible_transport_v1(v_history_company,p_organization_id,p_branch_id,h.organization_id,h.scope_type,h.scope_id) ORDER BY h.id DESC LIMIT 1; END IF;\n IF p_action='finish' THEN\n  SELECT count(*)::text INTO v_count FROM public.change_history h WHERE public.pos_sync_history_row_visible_transport_v1(v_history_company,p_organization_id,p_branch_id,h.organization_id,h.scope_type,h.scope_id) AND v_upper IS NOT NULL AND h.id<=v_upper;\n ELSE\n  WITH candidates AS MATERIALIZED (\n   SELECT h.id FROM public.change_history h WHERE public.pos_sync_history_row_visible_transport_v1(v_history_company,p_organization_id,p_branch_id,h.organization_id,h.scope_type,h.scope_id) AND v_upper IS NOT NULL AND h.id<=v_upper AND (p_after_id IS NULL OR h.id>p_after_id)\n   ORDER BY h.id LIMIT p_limit+1\n  ), selected AS (SELECT id FROM candidates ORDER BY id LIMIT p_limit)\n  SELECT COALESCE((SELECT jsonb_agg(id::text ORDER BY id) FROM selected),'[]'::jsonb),(SELECT count(*) FROM candidates)>p_limit\n   INTO v_ids,v_more;\n  IF v_more THEN v_next:=(v_ids->>-1)::uuid; END IF;\n END IF;\n v_result:=jsonb_build_object('protocol','history-index-v2','policy','branch-history-v1','history_scope',CASE WHEN v_history_company THEN 'company' ELSE 'branch' END,'projection','history-project-v1:a5be97695f3e105ebde271e2f017ddee',\n  'organization_id',p_organization_id,'branch_id',p_branch_id,'terminal_id',p_terminal_id,'keep_commerce',p_keep_commerce,\n  'action',p_action,'upper_id',v_upper,'after_id',p_after_id,'ids',v_ids,'next_id',v_next,'complete',NOT v_more,'range_count',v_count);\n IF octet_length(v_result::text)>131072 THEN RAISE EXCEPTION 'HISTORY_INDEX_OVERSIZED'; END IF;\n PERFORM set_config('response.headers',jsonb_build_array(\n  jsonb_build_object('X-POS-History-Reconcile-Version','2'),jsonb_build_object('X-POS-History-Reconcile-Kind','index'),\n  jsonb_build_object('X-POS-History-Reconcile-Bytes',octet_length(v_result::text)::text),\n  jsonb_build_object('X-POS-History-Reconcile-Rows',jsonb_array_length(v_ids)::text))::text,true);\n RETURN v_result;\nEND;\n$function$\n"},{"signature":"pos_sync_history_rows_v3(text,text,text,jsonb,boolean,integer)","acl_values":["postgres=X/postgres","service_role=X/postgres"],"owner":"postgres","config":["search_path=pg_catalog, public"],"definer":false,"strict":false,"volatility":"v","language":"plpgsql","returns":"jsonb","parallel":"u","cost":100,"rows":0,"leakproof":false,"support":"-","body_md5":"62d8d9a1cc8d1dbcb8b0d99a2c4714ac","definition_md5":"6a3120c5806cb19bf0a8a2231cfa7167","definition":"\u0043REATE FUNCTION public.pos_sync_history_rows_v3(p_organization_id text, p_branch_id text, p_terminal_id text, p_ids jsonb, p_keep_commerce boolean DEFAULT false, p_max_bytes integer DEFAULT 2097152)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\nDECLARE\n v_history_company boolean;\n v_id text; v_raw public.change_history%ROWTYPE; v_projected jsonb; v_wire jsonb;\n v_rows jsonb:='[]'::jsonb; v_candidate jsonb; v_result jsonb; v_remaining jsonb; v_count integer:=0; v_bytes integer;\nBEGIN\n v_history_company := public.pos_sync_history_company_scope_transport_v1(p_organization_id,p_branch_id,p_terminal_id);\n IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('public.pos_sync_history_project_v1(jsonb,text,boolean)')\n  AND md5(replace(p.prosrc,chr(13)||chr(10),chr(10)))='a5be97695f3e105ebde271e2f017ddee'\n  AND pg_get_userbyid(p.proowner)='postgres' AND p.prorettype='jsonb'::regtype AND p.prolang=(SELECT oid FROM pg_language WHERE lanname='plpgsql')\n  AND NOT p.prosecdef AND p.proisstrict AND p.provolatile='i' AND p.proconfig=ARRAY['search_path=pg_catalog'])\n OR NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('public.change_history_immutable()')\n  AND replace(p.prosrc,chr(13)||chr(10),chr(10)) IN (chr(10)||'BEGIN RAISE EXCEPTION ''change_history is append-only''; END ',' BEGIN RAISE EXCEPTION ''change_history is append-only''; END ')\n  AND pg_get_userbyid(p.proowner)='postgres' AND p.prorettype='trigger'::regtype AND p.prolang=(SELECT oid FROM pg_language WHERE lanname='plpgsql')\n  AND NOT p.prosecdef AND NOT p.proisstrict AND p.provolatile='v' AND p.proconfig=ARRAY['search_path=public, pg_temp'])\n OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.change_history'::regclass AND tgname='change_history_no_change' AND tgenabled='O'\n  AND pg_get_triggerdef(oid)='CREATE TRIGGER change_history_no_change BEFORE DELETE OR UPDATE ON public.change_history FOR EACH ROW EXECUTE FUNCTION change_history_immutable()')\n THEN RAISE EXCEPTION 'HISTORY_INDEX_UNSUPPORTED_SOURCE'; END IF;\n IF p_ids IS NULL OR jsonb_typeof(p_ids)<>'array' OR jsonb_array_length(p_ids)<1 OR jsonb_array_length(p_ids)>10\n OR p_keep_commerce IS NULL OR p_max_bytes IS NULL OR p_max_bytes<1024 OR p_max_bytes>2097152\n THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='HISTORY_ROWS_INVALID_ARGUMENT'; END IF;\n IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_ids) x(value) WHERE jsonb_typeof(value)<>'string'\n   OR (value#>>'{}')!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')\n OR (SELECT count(DISTINCT value) FROM jsonb_array_elements(p_ids))<>jsonb_array_length(p_ids)\n THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='HISTORY_ROWS_INVALID_IDS'; END IF;\n FOR v_id IN SELECT value FROM jsonb_array_elements_text(p_ids) LOOP\n  SELECT * INTO v_raw FROM public.change_history h WHERE h.id=v_id::uuid AND public.pos_sync_history_row_visible_transport_v1(v_history_company,p_organization_id,p_branch_id,h.organization_id,h.scope_type,h.scope_id);\n  IF NOT FOUND THEN RAISE EXCEPTION 'HISTORY_INDEX_ROW_MISSING'; END IF;\n  IF NOT isfinite(v_raw.server_timestamp) OR v_raw.server_timestamp<'0001-01-01T00:00:00Z'::timestamptz\n   OR v_raw.server_timestamp>'9999-12-31T23:59:59.999999Z'::timestamptz\n   THEN RAISE EXCEPTION 'HISTORY_ROWS_TIMESTAMP_UNSUPPORTED'; END IF;\n  v_projected:=public.pos_sync_history_project_v1(to_jsonb(v_raw),'change_history',p_keep_commerce);\n  v_wire:=(v_projected-'old_value'-'new_value'-'revision'-'server_timestamp')||jsonb_build_object(\n   'old_value_json',CASE WHEN v_projected->'old_value'='null'::jsonb THEN NULL ELSE (v_projected->'old_value')::text END,\n   'new_value_json',CASE WHEN v_projected->'new_value'='null'::jsonb THEN NULL ELSE (v_projected->'new_value')::text END,\n   'revision',v_raw.revision::text,\n   'server_timestamp',to_char(v_raw.server_timestamp AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS.US')||'0Z');\n  SELECT COALESCE(jsonb_agg(value ORDER BY ordinality),'[]'::jsonb) INTO v_remaining\n   FROM jsonb_array_elements(p_ids) WITH ORDINALITY x(value,ordinality) WHERE ordinality>v_count+1;\n  v_candidate:=jsonb_build_object('protocol','history-rows-v2','policy','branch-history-v1','history_scope',CASE WHEN v_history_company THEN 'company' ELSE 'branch' END,'projection','history-project-v1:a5be97695f3e105ebde271e2f017ddee',\n   'organization_id',p_organization_id,'branch_id',p_branch_id,'terminal_id',p_terminal_id,'keep_commerce',p_keep_commerce,\n   'requested_ids',p_ids,'rows',v_rows||jsonb_build_array(v_wire),'remaining_ids',v_remaining);\n  v_bytes:=octet_length(v_candidate::text);\n  IF v_bytes>p_max_bytes AND v_count>0 THEN EXIT; END IF;\n  IF v_bytes>5242880 THEN RAISE EXCEPTION USING ERRCODE='54000',MESSAGE='HISTORY_ROWS_SINGLE_ROW_TOO_LARGE'; END IF;\n  v_result:=v_candidate;v_rows:=v_rows||jsonb_build_array(v_wire);v_count:=v_count+1;\n  IF v_bytes>p_max_bytes THEN EXIT; END IF;\n END LOOP;\n IF v_result IS NULL THEN RAISE EXCEPTION 'HISTORY_ROWS_EMPTY'; END IF;\n PERFORM set_config('response.headers',jsonb_build_array(\n  jsonb_build_object('X-POS-History-Reconcile-Version','2'),\n  jsonb_build_object('X-POS-History-Reconcile-Kind','rows'),\n  jsonb_build_object('X-POS-History-Reconcile-Bytes',octet_length(v_result::text)::text),\n  jsonb_build_object('X-POS-History-Reconcile-Rows',v_count::text))::text,true);\n RETURN v_result;\nEND;\n$function$\n"},{"signature":"pos_sync_history_page_v2(text,text,text,text,integer,boolean,integer)","acl_values":["postgres=X/postgres","service_role=X/postgres"],"owner":"postgres","config":["search_path=pg_catalog"],"definer":false,"strict":false,"volatility":"v","language":"plpgsql","returns":"jsonb","parallel":"u","cost":100,"rows":0,"leakproof":false,"support":"-","body_md5":"340d95051caa13ff2baee75baa0b1ab7","definition_md5":"0e9b27e8d1b0c01643482532c8a3accf","definition":"\u0043REATE FUNCTION public.pos_sync_history_page_v2(p_organization_id text, p_branch_id text, p_terminal_id text, p_after_cursor text DEFAULT NULL::text, p_history_days integer DEFAULT 90, p_keep_commerce boolean DEFAULT false, p_max_bytes integer DEFAULT 2097152)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog'\nAS $function$\nDECLARE\n  v_history_company boolean;\n  v_after_id uuid;\n  v_cursor_json jsonb;\n  v_ids uuid[];\n  v_history public.change_history%ROWTYPE;\n  v_rows jsonb := '[]'::jsonb;\n  v_row jsonb;\n  v_projected jsonb;\n  v_envelope jsonb;\n  v_candidate jsonb;\n  v_cursor text;\n  v_last_id uuid;\n  v_count integer := 0;\n  v_total integer;\n  v_bytes integer;\n  v_hard constant integer := 5242880;\nBEGIN\n v_history_company := public.pos_sync_history_company_scope_transport_v1(p_organization_id,p_branch_id,p_terminal_id);\n -- Runtime accepts only the same reviewed projection with LF/CRLF storage,\n -- and the captured-live/current-canonical immutable helper body forms.\n -- The migration's existing-source preflight below remains byte-exact.\n IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('public.pos_sync_history_project_v1(jsonb,text,boolean)')\n  AND md5(replace(p.prosrc,chr(13)||chr(10),chr(10)))='a5be97695f3e105ebde271e2f017ddee'\n  AND pg_get_userbyid(p.proowner)='postgres' AND p.prorettype='jsonb'::regtype AND p.prolang=(SELECT oid FROM pg_language WHERE lanname='plpgsql')\n  AND NOT p.prosecdef AND p.proisstrict AND p.provolatile='i' AND p.proconfig=ARRAY['search_path=pg_catalog'])\n OR NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('public.change_history_immutable()')\n  AND replace(p.prosrc,chr(13)||chr(10),chr(10)) IN (chr(10)||'BEGIN RAISE EXCEPTION ''change_history is append-only''; END ',' BEGIN RAISE EXCEPTION ''change_history is append-only''; END ')\n  AND pg_get_userbyid(p.proowner)='postgres' AND p.prorettype='trigger'::regtype AND p.prolang=(SELECT oid FROM pg_language WHERE lanname='plpgsql')\n  AND NOT p.prosecdef AND NOT p.proisstrict AND p.provolatile='v' AND p.proconfig=ARRAY['search_path=public, pg_temp'])\n OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.change_history'::regclass AND tgname='change_history_no_change' AND tgenabled='O'\n  AND pg_get_triggerdef(oid)='CREATE TRIGGER change_history_no_change BEFORE DELETE OR UPDATE ON public.change_history FOR EACH ROW EXECUTE FUNCTION public.change_history_immutable()')\n THEN RAISE EXCEPTION 'HISTORY_INDEX_UNSUPPORTED_SOURCE'; END IF;\n  IF p_max_bytes IS NULL OR p_max_bytes < 1024 OR p_max_bytes > 2097152 OR p_keep_commerce IS NULL THEN\n    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='POS_HISTORY_STREAM_INVALID_ARGUMENT';\n  END IF;\n  IF p_history_days IS NULL OR p_history_days NOT BETWEEN 30 AND 7300 THEN\n    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='POS_HISTORY_STREAM_INVALID_ARGUMENT';\n  END IF;\n  IF p_after_cursor IS NOT NULL THEN\n    BEGIN\n      v_cursor_json := p_after_cursor::jsonb;\n      IF jsonb_typeof(v_cursor_json) IS DISTINCT FROM 'object'\n       OR jsonb_typeof(v_cursor_json->'id') IS DISTINCT FROM 'string' OR v_cursor_json-'id'<>'{}'::jsonb\n       OR v_cursor_json->>'id' !~ '^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}$'\n      THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='POS_HISTORY_STREAM_INVALID_ARGUMENT'; END IF;\n      v_after_id := (v_cursor_json->>'id')::uuid;\n    EXCEPTION WHEN invalid_text_representation THEN\n      RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='POS_HISTORY_STREAM_INVALID_ARGUMENT';\n    END;\n  END IF;\n  SELECT COALESCE(array_agg(page.id ORDER BY page.id),ARRAY[]::uuid[]) INTO v_ids FROM (\n    SELECT h.id FROM public.change_history h\n    WHERE (v_after_id IS NULL OR h.id>v_after_id)\n      AND public.pos_sync_history_row_visible_transport_v1(v_history_company,p_organization_id,p_branch_id,h.organization_id,h.scope_type,h.scope_id)\n    ORDER BY h.id LIMIT 10\n  ) page;\n  v_total := cardinality(v_ids);\n  FOREACH v_last_id IN ARRAY v_ids LOOP\n    SELECT h.* INTO v_history FROM public.change_history h WHERE h.id=v_last_id\n      AND public.pos_sync_history_row_visible_transport_v1(v_history_company,p_organization_id,p_branch_id,h.organization_id,h.scope_type,h.scope_id);\n    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='POS_HISTORY_STREAM_INVALID_SOURCE'; END IF;\n    v_row := to_jsonb(v_history);\n    v_projected := public.pos_sync_history_project_v1(v_row,'change_history',p_keep_commerce);\n    v_cursor := CASE WHEN v_count+1=v_total AND v_total<10 THEN NULL ELSE pg_catalog.jsonb_build_object('id',v_last_id)::text END;\n    v_candidate := pg_catalog.jsonb_build_object('rows',v_rows||pg_catalog.jsonb_build_array(v_projected),'cursor',v_cursor);\n    v_bytes := pg_catalog.octet_length(v_candidate::text);\n    IF v_bytes > p_max_bytes AND v_count > 0 THEN EXIT; END IF;\n    IF v_bytes > v_hard THEN RAISE EXCEPTION USING ERRCODE='54000',MESSAGE='POS_HISTORY_STREAM_ROW_TOO_LARGE'; END IF;\n    v_rows := v_rows||pg_catalog.jsonb_build_array(v_projected);\n    v_count := v_count+1;\n    v_envelope := v_candidate;\n    IF v_bytes > p_max_bytes THEN EXIT; END IF;\n  END LOOP;\n  IF v_count=0 THEN v_envelope := pg_catalog.jsonb_build_object('rows','[]'::jsonb,'cursor',NULL); END IF;\n  -- A prefix cut must resume from the last KEPT raw UUID, never the lookahead.\n  IF v_count < v_total THEN\n    v_envelope := pg_catalog.jsonb_set(v_envelope,ARRAY['cursor'],pg_catalog.to_jsonb(pg_catalog.jsonb_build_object('id',v_rows->(v_count-1)->>'id')::text));\n  END IF;\n  v_bytes := pg_catalog.octet_length(v_envelope::text);\n  IF v_bytes > v_hard THEN RAISE EXCEPTION USING ERRCODE='54000',MESSAGE='POS_HISTORY_STREAM_ROW_TOO_LARGE'; END IF;\n  PERFORM pg_catalog.set_config('response.headers',pg_catalog.jsonb_build_array(\n    pg_catalog.jsonb_build_object('X-POS-History-Projection','1'),\n    pg_catalog.jsonb_build_object('X-POS-History-Bytes',v_bytes::text),\n    pg_catalog.jsonb_build_object('X-POS-History-Rows',v_count::text)\n  )::text,true);\n  RETURN v_envelope;\nEND;\n$function$\n"},{"signature":"pos_sync_feed_page_v2(text,text,text,bigint,boolean,integer)","acl_values":["postgres=X/postgres","service_role=X/postgres"],"owner":"postgres","config":["search_path=pg_catalog"],"definer":false,"strict":false,"volatility":"v","language":"plpgsql","returns":"jsonb","parallel":"u","cost":100,"rows":0,"leakproof":false,"support":"-","body_md5":"f70a21ddf867544c9c879c3d52378bdb","definition_md5":"63ed67059d53024429eee713d4999eef","definition":"\u0043REATE FUNCTION public.pos_sync_feed_page_v2(p_organization_id text, p_branch_id text, p_terminal_id text, p_after_cursor bigint DEFAULT 0, p_keep_commerce boolean DEFAULT false, p_max_bytes integer DEFAULT 2097152)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog'\nAS $function$\nDECLARE\n v_raw jsonb; v_rows jsonb := '[]'::jsonb; v_row jsonb; v_projected jsonb; v_candidate jsonb;\n v_previous bigint := p_after_cursor; v_cursor bigint; v_raw_count integer; v_count integer := 0;\n v_bytes integer; v_more boolean; v_hard constant integer := 5242880;\nBEGIN\n IF pg_catalog.md5(pg_catalog.pg_get_functiondef(pg_catalog.to_regprocedure('public.pos_sync_pull_history_v2(text,text,text,bigint,integer)'))) IS DISTINCT FROM '34f17c081b8a69e687880c6b67bf7217'\n OR pg_catalog.md5(pg_catalog.pg_get_functiondef(pg_catalog.to_regprocedure('public.pos_sync_history_project_v1(jsonb,text,boolean)'))) IS DISTINCT FROM '4633e04e150c350518938f2ba661fca1' THEN\n  RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='POS_FEED_STREAM_UNSUPPORTED_SOURCE';\n END IF;\n IF p_after_cursor IS NULL OR p_keep_commerce IS NULL OR p_max_bytes IS NULL OR p_max_bytes<1024 OR p_max_bytes>2097152 THEN\n  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='POS_FEED_STREAM_INVALID_ARGUMENT';\n END IF;\n -- The existing delegate alone admits branch/terminal scope and returns its\n -- existing visible records. Its hard lower bound is ten, so request ten.\n SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(f) ORDER BY f.cursor),'[]'::jsonb)\n INTO v_raw FROM public.pos_sync_pull_history_v2(p_organization_id,p_branch_id,p_terminal_id,p_after_cursor,10) f;\n v_raw_count:=pg_catalog.jsonb_array_length(v_raw);\n IF v_raw_count>10 THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='POS_FEED_STREAM_INVALID_SOURCE'; END IF;\n -- Validate every raw cursor before emitting any prefix; never advance over\n -- malformed source data. JSONB retains exact signed bigint values.\n FOR v_row IN SELECT a.value FROM pg_catalog.jsonb_array_elements(v_raw) a(value) LOOP\n  v_cursor:=(v_row->>'cursor')::bigint;\n  IF v_cursor IS NULL OR v_cursor<=v_previous THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='POS_FEED_STREAM_INVALID_SOURCE'; END IF;\n  v_previous:=v_cursor;\n END LOOP;\n FOR v_row IN SELECT a.value FROM pg_catalog.jsonb_array_elements(v_raw) a(value) LOOP\n  v_projected:=public.pos_sync_history_project_v1(v_row,'',p_keep_commerce);\n  v_candidate:=v_rows||pg_catalog.jsonb_build_array(v_projected);\n  v_bytes:=pg_catalog.octet_length(v_candidate::text);\n  IF v_bytes>p_max_bytes AND v_count>0 THEN EXIT; END IF;\n  IF v_bytes>v_hard THEN RAISE EXCEPTION USING ERRCODE='54000',MESSAGE='POS_FEED_STREAM_ROW_TOO_LARGE'; END IF;\n  v_rows:=v_candidate; v_count:=v_count+1;\n  IF v_bytes>p_max_bytes THEN EXIT; END IF;\n END LOOP;\n v_bytes:=pg_catalog.octet_length(v_rows::text);\n v_more:=v_count<v_raw_count OR v_raw_count=10;\n PERFORM pg_catalog.set_config('response.headers',pg_catalog.jsonb_build_array(\n  pg_catalog.jsonb_build_object('X-POS-Feed-Projection','1'),\n  pg_catalog.jsonb_build_object('X-POS-Feed-Bytes',v_bytes::text),\n  pg_catalog.jsonb_build_object('X-POS-Feed-Rows',v_count::text),\n  pg_catalog.jsonb_build_object('X-POS-Feed-Continue',CASE WHEN v_more THEN '1' ELSE '0' END)\n )::text,true);\n RETURN v_rows;\nEND;\n$function$\n"},{"signature":"pos_sync_counts_history_v2(text,text,text,integer)","acl_values":["postgres=X/postgres","service_role=X/postgres"],"owner":"postgres","config":["search_path=public, pg_temp"],"definer":true,"strict":false,"volatility":"v","language":"plpgsql","returns":"TABLE(table_name text, row_count bigint)","parallel":"u","cost":100,"rows":1000,"leakproof":false,"support":"-","body_md5":"11e168afd9172b4d44fff104e27426cd","definition_md5":"ba245eb99e324d0aaae49972c98dd9e1","definition":"\u0043REATE FUNCTION public.pos_sync_counts_history_v2(p_organization_id text, p_branch_id text, p_terminal_id text, p_history_days integer DEFAULT 90)\n RETURNS TABLE(table_name text, row_count bigint)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE v_history_company boolean;\nBEGIN\n v_history_company := public.pos_sync_history_company_scope_transport_v1(p_organization_id,p_branch_id,p_terminal_id);\n  RETURN QUERY\n    SELECT scoped.table_name,scoped.row_count\n    FROM public.pos_sync_counts_scoped(\n      p_organization_id,p_branch_id,p_terminal_id,p_history_days\n    ) scoped\n    WHERE scoped.table_name NOT IN ('issued_vouchers','change_history')\n    UNION ALL\n    SELECT 'issued_vouchers'::text,count(*)::bigint FROM public.issued_vouchers\n    UNION ALL\n    SELECT 'change_history'::text,count(*)::bigint FROM public.change_history h WHERE public.pos_sync_history_row_visible_transport_v1(v_history_company,p_organization_id,p_branch_id,h.organization_id,h.scope_type,h.scope_id);\nEND $function$\n"}]$history_transport_data$::jsonb;
 history_shape constant jsonb := $history_transport_data$[{"name":"id","type":"uuid","not_null":true},{"name":"organization_id","type":"text","not_null":true},{"name":"entity_type","type":"text","not_null":true},{"name":"entity_id","type":"text","not_null":true},{"name":"action","type":"text","not_null":true},{"name":"old_value","type":"jsonb","not_null":false},{"name":"new_value","type":"jsonb","not_null":false},{"name":"revision","type":"bigint","not_null":true},{"name":"scope_type","type":"text","not_null":true},{"name":"scope_id","type":"text","not_null":false},{"name":"changed_by","type":"text","not_null":false},{"name":"source_application","type":"text","not_null":true},{"name":"device_id","type":"text","not_null":false},{"name":"terminal_id","type":"text","not_null":false},{"name":"server_timestamp","type":"timestamp with time zone","not_null":true}]$history_transport_data$::jsonb;
 entry jsonb; actual jsonb; fn oid; installed integer:=0;
BEGIN
 IF current_user<>'postgres' THEN RAISE EXCEPTION 'HISTORY_TRANSPORT_OWNER'; END IF;
 PERFORM set_config('search_path','pg_catalog,public',true);
 LOCK TABLE public.change_history,public.sync_change_feed IN ACCESS SHARE MODE NOWAIT;
 SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull) ORDER BY a.attnum)
 INTO actual FROM pg_attribute a WHERE a.attrelid='public.change_history'::regclass AND a.attnum>0 AND NOT a.attisdropped;
 IF actual IS DISTINCT FROM history_shape
 OR NOT EXISTS(SELECT 1 FROM pg_class WHERE oid='public.change_history'::regclass AND relrowsecurity AND pg_get_userbyid(relowner)='postgres')
 OR NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='public.change_history'::regclass AND contype='p' AND conkey=ARRAY[1]::smallint[] AND convalidated AND NOT condeferrable)
 OR (SELECT count(*) FROM pg_trigger WHERE tgrelid='public.change_history'::regclass AND NOT tgisinternal)<>1
 OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.change_history'::regclass AND tgname='change_history_no_change' AND tgenabled='O'
  AND pg_get_triggerdef(oid)='CREATE TRIGGER change_history_no_change BEFORE DELETE OR UPDATE ON public.change_history FOR EACH ROW EXECUTE FUNCTION change_history_immutable()')
 THEN RAISE EXCEPTION 'HISTORY_TRANSPORT_SHAPE'; END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(dependencies) LOOP
  fn:=to_regprocedure('public.'||(entry->>'signature'));
  IF fn IS NULL OR NOT (entry->'definition_hashes' ? md5(replace(pg_get_functiondef(fn),chr(13)||chr(10),chr(10))))
  THEN RAISE EXCEPTION 'HISTORY_TRANSPORT_SOURCE_CHANGED: %',entry->>'signature'; END IF;
 END LOOP;
 FOR entry IN SELECT value FROM jsonb_array_elements(targets) LOOP
  fn:=to_regprocedure('public.'||(entry->>'signature'));
  IF fn IS NOT NULL THEN installed:=installed+1; END IF;
 END LOOP;
 IF installed NOT IN (0,jsonb_array_length(targets)) THEN RAISE EXCEPTION 'HISTORY_TRANSPORT_PARTIAL'; END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(dependencies||targets) WITH ORDINALITY AS routines(value,position) ORDER BY position LOOP
  IF installed=0 AND entry ? 'definition' THEN
   EXECUTE entry->>'definition';
   EXECUTE 'REVOKE ALL ON FUNCTION public.'||(entry->>'signature')||' FROM PUBLIC,anon,authenticated,service_role';
   EXECUTE 'GRANT EXECUTE ON FUNCTION public.'||(entry->>'signature')||' TO service_role';
  END IF;
  fn:=to_regprocedure('public.'||(entry->>'signature'));
  IF NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=fn
   AND pg_get_userbyid(p.proowner)=entry->>'owner' AND (SELECT jsonb_agg(v::text ORDER BY v::text) FROM unnest(p.proacl)v)=entry->'acl_values'
   AND to_jsonb(p.proconfig)=entry->'config' AND p.prosecdef=(entry->>'definer')::boolean AND p.proisstrict=(entry->>'strict')::boolean
   AND p.provolatile::text=entry->>'volatility' AND l.lanname=entry->>'language' AND pg_get_function_result(p.oid)=entry->>'returns'
   AND p.prokind='f' AND p.proparallel::text=entry->>'parallel' AND p.procost=(entry->>'cost')::real
   AND p.prorows=(entry->>'rows')::real AND p.proleakproof=(entry->>'leakproof')::boolean AND p.prosupport::text=entry->>'support'
   AND (NOT(entry ? 'body_md5') OR md5(replace(p.prosrc,chr(13)||chr(10),chr(10)))=entry->>'body_md5')
   AND (NOT(entry ? 'definition_md5') OR md5(replace(pg_get_functiondef(fn),chr(13)||chr(10),chr(10)))=entry->>'definition_md5')
   AND (NOT(entry ? 'arguments') OR pg_get_function_arguments(fn)=entry->>'arguments'))
  THEN RAISE EXCEPTION 'HISTORY_TRANSPORT_METADATA: %',entry->>'signature'; END IF;
 END LOOP;
END;
$history_transport_upgrade$;
